import{_ as s,o as e,c as n,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"镜像源配置","description":"","frontmatter":{},"headers":[],"relativePath":"system-config/mirror.md","filePath":"system-config/mirror.md","lastUpdated":1791914987000}'),i={name:"system-config/mirror.md"};function c(p,a,r,o,l,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="镜像源配置" tabindex="-1">镜像源配置 <a class="header-anchor" href="#镜像源配置" aria-label="Permalink to &quot;镜像源配置&quot;">​</a></h1><h2 id="官方源-清华大学" tabindex="-1">官方源（清华大学） <a class="header-anchor" href="#官方源-清华大学" aria-label="Permalink to &quot;官方源（清华大学）&quot;">​</a></h2><p>镜像列表文件在 <code>/etc/pacman.d/mirrorlist</code>，越靠前的源优先级越高，先备份一份</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo cp /etc/pacman.d/mirrorlist /etc/pacman.d/mirrorlist.bak</span></span></code></pre></div><p>把清华源写到文件第一行（<code>$repo</code>、<code>$arch</code> 保持原样，不要替换）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Server = https://mirrors.tuna.tsinghua.edu.cn/archlinux/$repo/os/$arch</span></span></code></pre></div><p>一键写法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo sed -i &#39;1i Server = https://mirrors.tuna.tsinghua.edu.cn/archlinux/$repo/os/$arch&#39; /etc/pacman.d/mirrorlist</span></span></code></pre></div><h2 id="archlinuxcn-清华" tabindex="-1">archlinuxcn（清华） <a class="header-anchor" href="#archlinuxcn-清华" aria-label="Permalink to &quot;archlinuxcn（清华）&quot;">​</a></h2><p>archlinuxcn 是中文社区仓库，里面有 yay、fcitx5 相关的很多包。打开 <code>/etc/pacman.conf</code>，在末尾加上</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[archlinuxcn]</span></span>
<span class="line"><span>Server = https://mirrors.tuna.tsinghua.edu.cn/archlinuxcn/$arch</span></span></code></pre></div><p>装完仓库配置后，必须导入签名密钥，否则安装包会报签名错误</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo pacman -Syy</span></span>
<span class="line"><span>sudo pacman -S archlinuxcn-keyring</span></span></code></pre></div><h2 id="其他常用镜像站" tabindex="-1">其他常用镜像站 <a class="header-anchor" href="#其他常用镜像站" aria-label="Permalink to &quot;其他常用镜像站&quot;">​</a></h2><p>官方源（<code>mirrorlist</code> 里用这行格式）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Server = https://mirrors.ustc.edu.cn/archlinux/$repo/os/$arch</span></span>
<span class="line"><span>Server = https://mirrors.bfsu.edu.cn/archlinux/$repo/os/$arch</span></span>
<span class="line"><span>Server = https://mirrors.aliyun.com/archlinux/$repo/os/$arch</span></span>
<span class="line"><span>Server = https://mirrors.cloud.tencent.com/archlinux/$repo/os/$arch</span></span></code></pre></div><p>archlinuxcn（<code>pacman.conf</code> 里用这行格式）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Server = https://mirrors.ustc.edu.cn/archlinuxcn/$arch</span></span>
<span class="line"><span>Server = https://mirrors.bfsu.edu.cn/archlinuxcn/$arch</span></span></code></pre></div><h2 id="刷新与生效" tabindex="-1">刷新与生效 <a class="header-anchor" href="#刷新与生效" aria-label="Permalink to &quot;刷新与生效&quot;">​</a></h2><p>改完源之后刷新数据库并升级</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo pacman -Syyu</span></span></code></pre></div><h2 id="签名报错的处理" tabindex="-1">签名报错的处理 <a class="header-anchor" href="#签名报错的处理" aria-label="Permalink to &quot;签名报错的处理&quot;">​</a></h2><p>如果装 archlinuxcn 的包时出现 <code>signature from ... is unknown trust</code>，重新导入密钥</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo pacman -S archlinuxcn-keyring</span></span></code></pre></div><p>还是不行就手动信任社区维护者的密钥</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo pacman-key --lsign-key &quot;ci@archlinuxcn.org&quot;</span></span></code></pre></div>`,26)])])}const g=s(i,[["render",c]]);export{u as __pageData,g as default};
